mapper.select:
select c.id, c.name, c.room, c.begin_date as beginDate, c.end_date as endDate, c.master_id as masterId, e.name as masterName, c.create_time as createTime, c.update_time as updateTime, case when now() < c.begin_date then '未开班' when now() > c.end_date then '已结课' else '在读中' end as status from clazz c left join emp e on c.master_id = e.id
c.name like concat('%', #{name}, '%')
and c.begin_date between #{begin} and #{end}
and c.begin_date >= #{begin} -- //把三种情况写成一个if语句，这样写会更方便，而且不会出现空指针异常-->
and c.begin_date <= #{end}
order by c.update_time desc
